export const MONSTER_REACTIONS=["squash","stretch","flatten","inflate","spin","ragdoll","wall-stick","floor-bounce","airborne","vibrate","dragged","sucked","magnet-pulled","stunned","dizzy","charred","glitch"];
const THEME_WEIGHTS={performative:["magnet","stamp","chainsaw"],credit:["magnet","hammer","stamp"],passive:["pan","blower"],control:["magnet","vacuum","hammer"],comparison:["spring","blower"],insecurity:["hammer","vacuum"],anxiety:["blower","pan"],rumination:["chainsaw","vacuum"],exclusion:["spring","hammer"],irritation:["hammer","pan","chainsaw"]};
const MUTATION_WEIGHTS={giant:["hammer","stamp"],mini:["vacuum","pan"],clone:["chainsaw","blower"],glitch:["magnet","chainsaw"],"low-gravity":["spring","blower"],"extra-props":["vacuum","hammer"],"super-knockback":["spring","pan"]};
export function selectToybox(encounter,recent=[],count=3){const random=rng(hash(`${encounter.seed}|toybox`)),concepts=encounter.semanticDNA?.concepts||[],mutationIds=(encounter.mutationDNA||[]).map(x=>x.id),preferred=unique([...concepts.flatMap(x=>THEME_WEIGHTS[x]||[]),...mutationIds.flatMap(x=>MUTATION_WEIGHTS[x]||[]),...(encounter.toyboxDNA?.preferredWeaponThemes||[]).map(x=>String(x).toLowerCase()).filter(x=>WEAPONS[x])]),recentSet=new Set(recent.slice(0,9)),pool=Object.values(WEAPONS).map(w=>({...w,score:(preferred.includes(w.id)?4:1)-(recentSet.has(w.id)?2.5:0)+random()})).sort((a,b)=>b.score-a.score);return shuffle(pool.slice(0,6),random).slice(0,Math.max(2,Math.min(4,count)))}
export function weaponSVG(id){const c="#d7ff42",d="#171221",p="#ff567c";const map={hammer:`<svg viewBox="0 0 80 56"><path fill="${c}" d="M8 5h48v10h10v21H18V27H8z"/><path fill="${d}" d="M35 36h9v20h-9z"/><path fill="${p}" d="M18 15h38v11H18z"/></svg>`,chainsaw:`<svg viewBox="0 0 80 56"><path fill="${d}" stroke="${c}" stroke-width="5" d="M8 12h50l13 15-13 15H8z"/><path fill="${p}" d="M17 20h37v14H17z"/><path fill="${c}" d="M4 15h6v6H4zm0 20h6v6H4zm56-12h7v8h-7z"/></svg>`,pan:`<svg viewBox="0 0 80 56"><circle cx="26" cy="28" r="20" fill="${d}" stroke="${c}" stroke-width="6"/><path stroke="${p}" stroke-width="9" d="M44 30h32"/></svg>`,spring:`<svg viewBox="0 0 80 56"><path fill="none" stroke="${c}" stroke-width="6" d="M5 30l9-12 9 20 9-20 9 20 9-12"/><path fill="${p}" d="M48 12h24v32H48z"/><path fill="${d}" d="M55 18h10v20H55z"/></svg>`,magnet:`<svg viewBox="0 0 80 56"><path fill="none" stroke="${p}" stroke-width="15" d="M17 9v23q0 16 18 16t18-16V9"/><path fill="${c}" d="M9 4h16v14H9zm36 0h16v14H45z"/></svg>`,vacuum:`<svg viewBox="0 0 80 56"><path fill="${p}" d="M12 18h38v27H12z"/><circle fill="${d}" stroke="${c}" stroke-width="4" cx="22" cy="47" r="7"/><circle fill="${d}" stroke="${c}" stroke-width="4" cx="43" cy="47" r="7"/><path fill="${c}" d="M50 23h26v12H50z"/></svg>`,stamp:`<svg viewBox="0 0 80 56"><path fill="${c}" d="M27 3h26v23H27z"/><path fill="${p}" d="M18 22h44v15H18z"/><path fill="${d}" stroke="${c}" stroke-width="5" d="M8 35h64v17H8z"/></svg>`,blower:`<svg viewBox="0 0 80 56"><path fill="${p}" d="M9 12h36l14 14-14 17H9z"/><path fill="${c}" d="M45 21h30v13H45z"/><path stroke="${c}" stroke-width="4" d="M63 10h15M66 42h12M68 3h10"/></svg>`};return map[id]||map.pan}
export class WeaponDirector{
  constructor(root,encounter,recent,callbacks={}){this.root=root;this.callbacks=callbacks;this.items=selectToybox(encounter,recent,encounter.monsterDNA?.rarity==="BOSS"?4:3);this.available=[...this.items];this.dropped=[];this.active=null;this.pointer=null;this.loop=0;this.used=[];this.layer=document.createElement("div");this.layer.className="toybox-layer";root.appendChild(this.layer)}
  drop(reason="arena"){const weapon=this.available.shift();if(!weapon)return null;const el=document.createElement("button");el.className=`weapon-drop weapon-${weapon.id}`;el.dataset.weapon=weapon.id;el.innerHTML=`${weaponSVG(weapon.id)}<b>${weapon.label}</b><small>${reason.toUpperCase()}</small>`;el.style.setProperty("--drop-x",`${18+Math.random()*64}%`);el.addEventListener("click",()=>this.equip(weapon,el));this.layer.appendChild(el);this.dropped.push({weapon,el});requestAnimationFrame(()=>el.classList.add("landed"));this.callbacks.onDrop?.(weapon,reason);return weapon}
  equip(weapon,el){if(this.active?.el)this.active.el.classList.remove("equipped");this.active={weapon,el,remaining:weapon.uses};el.classList.add("equipped");this.callbacks.onEquip?.(weapon,this.active.remaining)}
  pointerDown(point){if(!this.active)return false;const w=this.active.weapon;this.pointer={point,start:performance.now(),last:point};if(w.continuous){this.callbacks.onStart?.(w);this.impact({charge:.35,continuous:true});this.loop=setInterval(()=>this.impact({charge:.45,continuous:true}),w.id==="chainsaw"?145:210)}else if(["pan","spring","stamp"].includes(w.id))this.impact({charge:1});else this.callbacks.onStart?.(w);return true}
  pointerMove(point){if(!this.pointer||!this.active)return;this.pointer.last=point;this.callbacks.onMove?.(this.active.weapon,point);if(this.active.weapon.id==="chainsaw"&&Math.random()>.6)this.impact({charge:.45,continuous:true,move:true})}
  pointerUp(point){if(!this.pointer||!this.active)return false;const w=this.active.weapon,charge=Math.min(1,(performance.now()-this.pointer.start)/850);clearInterval(this.loop);this.loop=0;if(!w.continuous&&!["pan","spring","stamp"].includes(w.id))this.impact({charge});this.callbacks.onStop?.(w,point);this.pointer=null;return true}
  impact(extra={}){if(!this.active)return;const current=this.active,w=current.weapon;current.remaining--;if(!this.used.includes(w.id))this.used.push(w.id);this.callbacks.onImpact?.(w,{...extra,remaining:current.remaining});this.callbacks.onUse?.(w,current.remaining);if(current.remaining<=0)this.breakActive()}
  breakActive(){if(!this.active)return;clearInterval(this.loop);const {weapon,el}=this.active;el.classList.add("weapon-broken");this.callbacks.onBreak?.(weapon);setTimeout(()=>el.remove(),720);this.active=null}
  releaseMode(){this.layer.classList.add("sandbox");if(this.available.length)this.drop("release")}
  stats(){return{offered:this.items.map(x=>x.id),used:[...this.used],active:this.active?.weapon.id||null,remaining:this.active?.remaining||0,dropped:this.dropped.length}}
  destroy(){clearInterval(this.loop);this.layer?.remove();this.root=null;this.callbacks={};this.available.length=0;this.dropped.length=0;this.active=null}
}
